16	// handleCreateResource handles 'ctrl+n' key - start unified group/project creation.
17	// Stashes parent info and loads templates from OCI registry before showing form.
18	func (m Model) handleCreateResource() (tea.Model, tea.Cmd) {
19		// Use the currently browsed group as parent, not the selected item.
20		// currentGroupNode is nil at root level.
21		parentName := ""
22		parentID := ""
23	
24		if m.currentGroupNode != nil {
25			parentName = m.currentGroupNode.FullPath
26			parentID = m.currentGroupNode.ID
27		}
28	
29		// Stash parent info for after template loading
30		m.creationParentName = parentName
31		m.creationParentID = parentID
32		m.mode = ModeLoadingTemplates
33	
34		return m, m.loadTemplates()
35	}
