37	// registryPassword reads the template registry's password from the secret
38	// store, keyed by the registry URL.
39	//
40	// It used to be config.Registry.Password — plaintext YAML, read on every
41	// template listing. The field is gone; a value left there by an older version
42	// was moved into the store at startup (§3.9).
43	//
44	// An empty result is not an error: an anonymous registry is the common case,
45	// and oci.NewClient treats empty credentials as "do not authenticate".
46	func (m Model) registryPassword() string {
47		if m.shared == nil || m.shared.Secrets.Storage == nil || m.config.Registry.URL == "" {
48			return ""
49		}
50		password, err := m.shared.Secrets.Storage.Load(m.config.Registry.URL)
51		if err != nil {
52			return ""
53		}
54		return password
55	}
