57	// loadTemplates loads available templates from the OCI registry catalog.
58	// Degrades gracefully: returns empty list if registry is not configured or on error.
59	func (m Model) loadTemplates() tea.Cmd {
60		registryURL := m.config.Registry.URL
61		basePath := m.config.Registry.TemplatesRepository
62		username := m.config.Registry.Username
63		password := m.registryPassword()
64	
65		return func() tea.Msg {
66			// If registry not configured, return empty (graceful degradation)
67			if registryURL == "" || basePath == "" {
68				return TemplatesLoadedMsg{}
69			}
70	
71			client := oci.NewClient(registryURL, username, password)
72			entries, err := client.ListTemplates(basePath)
73			if err != nil {
74				log.Printf("ERROR: failed to load templates from OCI registry: %v", err)
75				return TemplatesLoadedMsg{Error: err}
76			}
77	
78			return TemplatesLoadedMsg{Templates: entries}
79		}
80	}
