82	// handleTemplatesLoaded handles TemplatesLoadedMsg - creates the project form with loaded templates
83	func (m Model) handleTemplatesLoaded(msg TemplatesLoadedMsg) (tea.Model, tea.Cmd) {
84		m.mode = ModeCreatingProject
85		m.templateEntries = msg.Templates
86	
87		// Extract display names for the form
88		names := make([]string, len(msg.Templates))
89		for i, t := range msg.Templates {
90			names[i] = t.Name
91		}
92	
93		m.creationForm = components.NewCreationForm(
94			0, // defaultResourceType = namespace (user can switch with ←→)
95			m.creationParentName,
96			m.creationParentID,
97			m.config.Forge.DefaultVisibility,
98			names,
99			m.vocab(),
100		)
101		if msg.Error != nil {
102			m.creationForm.SetTemplateWarning(fmt.Sprintf("Registry error: %v", msg.Error))
103		}
104		return m, nil
105	}
