124	func (m Model) createGroup(msg components.CreationFormSubmitMsg) tea.Cmd {
125		backend := m.shared.Forge
126		spec := forge.NewNamespace{
127			Name:        msg.Name,
128			Slug:        slugify(msg.Name),
129			Description: msg.Description,
130			Visibility:  msg.Visibility,
131			ParentID:    msg.ParentID,
132		}
