148	// createProject creates a new GitLab project and optionally applies a template
149	func (m Model) createProject(msg components.CreationFormSubmitMsg) tea.Cmd {
150		backend := m.shared.Forge
151		spec := forge.NewRepository{
152			Name:        msg.Name,
153			Slug:        slugify(msg.Name),
154			Description: msg.Description,
155			Visibility:  msg.Visibility,
156			NamespaceID: msg.ParentID,
157		}
158		registryURL := m.config.Registry.URL
159		username := m.config.Registry.Username
160		password := m.registryPassword()
161	
162		// Resolve template entry from display name
163		var templateRepo, templateTag string
164		if msg.Template != "" {
165			for _, entry := range m.templateEntries {
166				if entry.Name == msg.Template {
167					templateRepo = entry.Repository
168					templateTag = entry.Tag
169					break
170				}
171			}
172		}
173	
174		return func() tea.Msg {
175			repo, err := backend.CreateRepository(context.Background(), spec)
176			if err != nil {
177				return ProjectCreatedMsg{Error: err}
178			}
179	
180			// Apply template if one was selected and resolved
181			if templateRepo != "" {
182				templateErr := applyTemplate(backend, repo.ID, registryURL, username, password, templateRepo, templateTag)
183				if templateErr != nil {
184					return ProjectCreatedMsg{Repository: repo, TemplateError: templateErr}
185				}
186			}
187	
188			return ProjectCreatedMsg{Repository: repo}
189		}
190	}
