192	// applyTemplate downloads an OCI template and commits its files to the project.
193	// This is a standalone function (not a method) because it runs inside a goroutine.
194	func applyTemplate(backend forge.Forge, repositoryID string, registryURL, username, password, repository, tag string) error {
195		ociClient := oci.NewClient(registryURL, username, password)
196	
197		tmpl, err := ociClient.DownloadTemplate(repository, tag)
198		if err != nil {
199			return fmt.Errorf("download template: %w", err)
200		}
201	
202		// Convert template files to commit actions
203		files := make([]forge.FileChange, 0, len(tmpl.Files))
204		for filePath, content := range tmpl.Files {
205			files = append(files, forge.FileChange{
206				Action:  forge.FileCreate,
207				Path:    filePath,
208				Content: content,
209			})
210		}
211	
212		if len(files) == 0 {
213			return nil
214		}
215	
216		return backend.InitialCommit(context.Background(), repositoryID, files)
217	}
