220	func (m Model) handleGroupCreated(msg GroupCreatedMsg) (tea.Model, tea.Cmd) {
221		if msg.Error != nil {
222			m.error = msg.Error.Error()
223			return m, nil
224		}
225		// Store path to select after refresh
226		m.pendingSelectPath = msg.Namespace.Path
227		// Refresh tree to show new group
228		return m.handleRefresh()
