231	// handleProjectCreated handles ProjectCreatedMsg
232	func (m Model) handleProjectCreated(msg ProjectCreatedMsg) (tea.Model, tea.Cmd) {
233		if msg.Error != nil {
234			m.error = msg.Error.Error()
235			return m, nil
236		}
237	
238		// Template application failed but project was created successfully
239		if msg.TemplateError != nil {
240			log.Printf("ERROR: template application failed: %v", msg.TemplateError)
241			m.error = fmt.Sprintf("Project created but template failed: %v", msg.TemplateError)
242		}
243	
244		// Store path to select after refresh
245		m.pendingSelectPath = msg.Repository.Path
246		// Refresh tree to show new project (even if template failed)
247		return m.handleRefresh()
248	}
