18	// View rend la vue
19	func (m Model) View() string {
20		// Priority 1: Forms (full viewport replacement - Rule 112)
21		if m.creationForm != nil {
22			return m.creationForm.View()
23		}
24	
25		// Priority 2: the clone list, which is a full viewport of its own — the
26		// progress view and the report both (decision 9).
27		if m.mode == ModeCloning && m.clone != nil {
28			return m.clone.table.View()
29		}
30	
31		// Priority 3: Modals (centered overlays)
32		switch m.mode {
33		case ModeLoadingTemplates:
34			return lipgloss.Place(
35				m.width, m.height,
36				lipgloss.Center, lipgloss.Center,
37				m.renderLoadingTemplates(),
38				lipgloss.WithWhitespaceBackground(theme.ColorBackground),
39			)
40		case ModeConfirmingDelete:
41			if m.deleteConfirmModal != nil {
42				return lipgloss.Place(
43					m.width, m.height,
44					lipgloss.Center, lipgloss.Center,
45					m.deleteConfirmModal.View(),
46					lipgloss.WithWhitespaceBackground(theme.ColorBackground),
47				)
48			}
49		}
50	
51		// Content style with left padding
52		contentStyle := lipgloss.NewStyle().Background(theme.ColorBackground).PaddingLeft(1)
53	
54		// Normal view
55		if !m.shared.IsAuthenticated {
56			return contentStyle.Render(renderNotAuthenticated(m.vocab()))
57		}
58	
59		if m.error != "" {
60			return contentStyle.Render(renderError(m.error))
61		}
62	
63		// The load says so in the footer, with a spinner, and the tree stays on
64		// screen (Rule 139): whether it is loading, genuinely empty, or filtered
65		// down to nothing, the body is the table alone — the row count is a header
66		// field instead.
67		return m.renderTable()
68	}
