100	// GetFooterHeight returns the footer height for this view (Rule 124).
101	//
102	// The clone list has no breadcrumb — it is a flat list, and the tree's path
103	// says nothing about it — so it takes the two-line footer plus its own filter
104	// bar.
105	func (m Model) GetFooterHeight() int {
106		if m.mode == ModeCloning && m.clone != nil {
107			return 2 + m.clone.table.FilterBar().ExtraHeight()
108		}
109		if m.showsTree() {
110			// filter bar (when visible) + breadcrumb tab bar + empty line + info line
111			return 3 + m.table.FilterBar().ExtraHeight()
112		}
113		return 2 // empty line + info line
114	}
115	
116	// RenderFooter returns the footer content rendered below the viewport (Rule 124).
117	func (m Model) RenderFooter(width int) string {
118		infoLine := m.renderInfoLine(width)
119	
120		if m.mode == ModeCloning && m.clone != nil {
121			var parts []string
122			if bar := m.clone.table.FilterBar(); bar.IsVisible() {
123				parts = append(parts, bar.View())
124			}
125			return strings.Join(append(parts, theme.EmptyLineBg(width), infoLine), "\n")
126		}
127	
128		if m.showsTree() {
129			var parts []string
130			if bar := m.table.FilterBar(); bar.IsVisible() {
131				parts = append(parts, bar.View())
132			}
133			parts = append(parts, m.renderTabBar(), theme.EmptyLineBg(width), infoLine)
134			return strings.Join(parts, "\n")
135		}
136		return theme.EmptyLineBg(width) + "\n" + infoLine
137	}
