145	// status is what the view derives on every frame. None of the three has a
146	// timer: a clone run outlives the three seconds a message gets, and the load
147	// and the selection last exactly as long as they last.
148	func (m Model) status() components.Status {
149		switch {
150		case m.mode == ModeCloning && m.clone != nil:
151			return components.Status{Text: m.cloneStatusLine()}
152		case m.mode == ModeSelecting:
153			return components.Status{Text: m.selectionStatusLine()}
154		case m.shared.IsAuthenticated && m.loadingTree():
155			return components.Status{Text: "Loading " + m.vocab().Name + " " + strings.ToLower(m.vocab().Namespaces) + "...", Spinner: true}
156		}
157		return components.Status{}
158	}
