160	// selectionStatusLine states the selection in the only terms it can: the
161	// repository count is not known until discovery has run (decision 7), so what
162	// is shown is what was actually chosen.
163	func (m Model) selectionStatusLine() string {
164		if m.selection.isEmpty() {
165			return "Select groups and projects with space, then press enter"
166		}
167		roots, exclusions := m.selection.counts()
168		line := plural(roots, "selection")
169		if exclusions > 0 {
170			line += " · " + plural(exclusions, "exclusion")
171		}
172		return line + " — enter to choose a destination"
173	}
