175	// showsTree reports whether the tree table is what is on screen, which is what
176	// decides whether the footer carries a breadcrumb and a filter bar.
177	func (m Model) showsTree() bool {
178		if !m.shared.IsAuthenticated || m.loading || m.error != "" || len(m.nodes) == 0 {
179			return false
180		}
181		if m.creationForm != nil {
182			return false
183		}
184		switch m.mode {
185		case ModeNormal, ModeSelecting:
186			return true
187		default:
188			return false
189		}
190	}
