192	// renderTabBar renders the tab bar at the bottom of the viewport
193	func (m Model) renderTabBar() string {
194		tabs := []theme.TabItem{{Label: theme.IconHome + " home"}}
195		for _, node := range m.navigationStack {
196			if node != nil {
197				tabs = append(tabs, theme.TabItem{Label: node.Name})
