251	// nodeKindRole is the same distinction as a colour, and it is what keeps the
252	// kind readable in the clone selection: there the glyph becomes a checkbox, so
253	// the hue is all that is left to say group or repository.
254	func nodeKindRole(node *TreeNode) theme.IconRole {
255		if node.Type == NodeTypeGroup {
256			return theme.IconRoleNamespace
257		}
258		return theme.IconRoleRepository
