261	// visibilityIcon is GitLab's and GitHub's own alphabet: a globe for what anyone
262	// can read, a shield for what a signed-in user can, a lock for neither.
263	//
264	// An unknown visibility renders **nothing** rather than a placeholder glyph. The
265	// field is the backend's, and a forge that grows a fourth value would otherwise
266	// show one of the three existing ones — a wrong answer where an empty cell is a
267	// true one.
268	func visibilityIcon(node *TreeNode) string {
269		switch node.Visibility {
270		case "public":
271			return theme.IconVisibilityPublic
272		case "internal":
273			return theme.IconVisibilityInternal
274		case "private":
275			return theme.IconLock
276		}
277		return ""
278	}
279	
280	// visibilityRole colours the glyph above. An unknown visibility has no role, so
281	// IconStyle falls back to plain text — which is what an empty cell should be.
282	func visibilityRole(node *TreeNode) theme.IconRole {
283		switch node.Visibility {
284		case "public":
285			return theme.IconRoleVisPublic
286		case "internal":
287			return theme.IconRoleVisInternal
288		case "private":
289			return theme.IconRoleVisPrivate
290		}
291		return ""
292	}
