294	// visibilityLabel returns the visibility label for a tree node
295	func visibilityLabel(node *TreeNode) string {
296		switch node.Visibility {
297		case "public":
298			return "Public"
299		case "internal":
300			return "Internal"
301		case "private":
302			return "Private"
303		default:
304			return ""
305		}
306	}
307	
308	// pipelineStatusLabel returns a status icon for the last CI pipeline.
309	//
310	// Every value forge.CIStatuses() declares has a case here, and
311	// TestEveryDeclaredCIStatusHasAnIcon walks that list to prove it. The default
312	// branch is therefore unreachable for a backend that keeps its promise — it
313	// stays because a backend that breaks it should still render *something*, and
314	// because that is how D66 was found: `created` and `scheduled` were missing
315	// from this switch, so a GitLab pipeline in either state printed its own name
316	// truncated to six cells.
317	//
318	// It switches on the constants rather than on literals so the two lists cannot
319	// drift again in silence: a renamed status stops compiling here.
320	func pipelineStatusLabel(node *TreeNode) string {
321		if node.Type != NodeTypeProject || node.PipelineStatus == "" {
322			return ""
323		}
324		switch node.PipelineStatus {
325		case forge.CIStatusSuccess:
326			return theme.IconOK
327		case forge.CIStatusFailed:
328			return theme.IconError
329		case forge.CIStatusRunning:
330			return theme.IconRunning
331		// The five ways a pipeline can have not started yet. They share one glyph
332		// because the difference between them is the scheduler's business, not the
333		// reader's: all five answer "nothing has run".
334		case forge.CIStatusPending, forge.CIStatusWaitingForResource, forge.CIStatusPreparing,
335			forge.CIStatusCreated, forge.CIStatusScheduled:
336			return theme.IconPending
337		case forge.CIStatusCanceled:
338			return theme.IconCanceled
339		case forge.CIStatusSkipped:
340			return theme.IconSkipped
341		case forge.CIStatusManual:
342			return theme.IconManual
343		default:
344			return node.PipelineStatus
345		}
346	}
347	
348	// pipelineStatusStyle colours the CI cell. A failed pipeline is the one thing
349	// in this table worth spotting without reading, and a green tick beside it is
350	// what makes it spottable — so success is coloured here where a running
351	// container is not: the CI column says nothing else, and most rows are not
352	// successes.
353	func pipelineStatusStyle(node *TreeNode) lipgloss.Style {
354		if node.Type != NodeTypeProject {
355			return theme.DimStyle
356		}
357		switch node.PipelineStatus {
358		case "success":
359			return theme.StatusOKStyle
360		case "failed":
361			return theme.StatusErrorStyle
362		case "running":
363			return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
364		case "canceled", "skipped", "manual", "":
365			return theme.DimStyle
366		default:
367			return theme.StatusWarningStyle
368		}
369	}
