396	// HeaderView interface implementation
397	
398	func (m Model) GetShortcuts() shortcut.Shortcuts {
399		// Mode-specific shortcuts
400		switch m.mode {
401		case ModeLoadingTemplates:
402			return []shortcut.Shortcut{}
403		case ModeSelecting:
404			// ←→ keeps drilling here, and that is the point: deselecting inside a
405			// ticked group means going into it (decision 10).
406			return []shortcut.Shortcut{
407				{Key: "space", Description: "Tick or untick"},
408				{Key: "←→", Description: "Open/Back"},
409				{Key: "enter", Description: "Choose a destination"},
410				{Key: "/", Description: "Search"},
411				{Key: "esc", Description: "Cancel"},
412			}
413		case ModeCloning:
414			return m.cloningShortcuts()
415		case ModeCreatingProject:
416			return []shortcut.Shortcut{
417				{Key: "↑↓", Description: "Navigate fields"},
418				{Key: "←→", Description: "Select option"},
419				{Key: "enter", Description: "Submit"},
420				{Key: "esc", Description: "Cancel"},
421			}
422		case ModeConfirmingDelete:
423			// ↑↓ is Rule 138 territory — obvious, so not advertised. It replaced
424			// tab here when D4 was fixed.
425			return []shortcut.Shortcut{
426				{Key: "space", Description: "Toggle"},
427				{Key: "y/n", Description: "Confirm"},
428				{Key: "esc", Description: "Cancel"},
429			}
430		}
431	
432		// Signed out is a different screen — there is no tree, so there is nothing
433		// to grey. That is a mode, not a state (Rule 130).
434		if !m.shared.IsAuthenticated {
435			return []shortcut.Shortcut{
436				{Key: "ctrl+p", Description: "Command mode"},
437			}
438		}
439	
440		// Normal mode. A load in flight greys the lot rather than emptying it: the
441		// tree is the same screen either side of a refresh, and a column that
442		// vanishes and comes back on every ctrl+r is the flicker Rule 130 is about.
443		loading := m.loading
444		browse := m.browsable()
445	
446		return []shortcut.Shortcut{
447			{Key: "←→", Description: "Open/Back", Disabled: loading},
448			{Key: keymap.New, Description: "New", Disabled: loading},
449			{Key: keymap.Delete, Description: "Delete", Disabled: loading},
450			{Key: keymap.Clone, Description: "Clone", Disabled: loading},
451			{Key: keymap.Web, Description: "Browser", Disabled: loading || !browse.Enabled()},
452			{Key: ".", Description: "Sort", Disabled: loading},
453			{Key: "/", Description: "Search", Disabled: loading},
454			{Key: "ctrl+r", Description: "Refresh"},
455			{Key: "ctrl+p", Description: "Command"},
456			{Key: "?", Description: "Help"},
457		}
458	}
