460	// reasonNoWebURL is why W does not apply. The row exists, it simply has no page.
461	const reasonNoWebURL = "This entry has no web page to open"
462	
463	// browsable reports whether W can open the selected row.
464	//
465	// Every node the forges return carries a WebURL, so in practice this only
466	// refuses on an empty level — but the handler already checked for it and
467	// returned in silence, which is what Rule 130 now forbids.
468	func (m Model) browsable() shortcut.Availability {
469		if node, ok := m.selectedNode(); !ok || node.WebURL == "" {
470			return shortcut.Unavailable(reasonNoWebURL)
471		}
472		return shortcut.Availability{}
473	}
474	
475	// cloningShortcuts is state-aware (Rule 130): `esc` means three different
476	// things across a run, and offering the same word for all three is how a user
477	// presses it a second time expecting it to force.
478	func (m Model) cloningShortcuts() shortcut.Shortcuts {
479		esc := shortcut.Shortcut{Key: "esc", Description: "Cancel"}
480		switch {
481		case m.clone == nil || m.clone.finished():
482			esc.Description = "Close"
483		case m.clone.cancelling:
484			esc.Description = "Waiting for the running clones"
485		}
486		return []shortcut.Shortcut{
487			esc,
488			{Key: "/", Description: "Search"},
489			{Key: ".", Description: "Sort"},
490			{Key: "?", Description: "Help"},
491		}
492	}
