494	func (m Model) GetTitle() string {
495		base := m.forgeIcon() + " " + m.vocab().Name + " Explorer"
496		if m.creationForm != nil {
497			return base + " " + theme.IconChevronRight + " " + m.creationForm.GetTitle()
498		}
499		switch m.mode {
500		case ModeSelecting:
501			return base + " " + theme.IconChevronRight + " Select what to clone"
502		case ModeCloning:
503			// The destination is in the title because it is the one thing the list
504			// does not repeat on every row, and it is what a user checks first.
505			if m.clone != nil {
506				return base + " " + theme.IconChevronRight + " Cloning into " + m.clone.target
507			}
508		}
509		return base
510	}
