32	// nodeFromRepository converts a repository.
33	func nodeFromRepository(repo forge.Repository, parent *TreeNode) *TreeNode {
34		return &TreeNode{
35			ID:                repo.ID,
36			Name:              repo.Name,
37			FullPath:          repo.Path,
38			Type:              NodeTypeProject,
39			Parent:            parent,
40			Expanded:          false,
41			Visibility:        repo.Visibility,
42			Role:              repo.Role,
43			CreatedAt:         repo.CreatedAt,
44			LastActivityAt:    repo.LastActivityAt,
