51	// discoverChildren walks a namespace for the recursive clone: the nodes it
52	// returns carry a type and a path, which is all a clone reads.
53	//
54	// It asks for no decoration, which is what keeps a clone from paying two extra
55	// requests per repository for a CI badge and a role it never looks at. The
56	// nodes are therefore **not** interchangeable with the ones the explorer
57	// browses, and must not be stored on the tree the view renders: the role and CI
58	// columns would go blank for every group a clone had walked through.
59	func discoverChildren(ctx context.Context, backend forge.Forge, parent *TreeNode, includeArchived bool) ([]*TreeNode, error) {
60		children, err := backend.Children(ctx, parent.ID, forge.BrowseOptions{IncludeArchived: includeArchived})
61		if err != nil {
62			return nil, err
63		}
64	
65		nodes := make([]*TreeNode, 0, len(children.Namespaces)+len(children.Repositories))
66		for _, ns := range children.Namespaces {
67			nodes = append(nodes, nodeFromNamespace(ns, parent))
68		}
69		for _, repo := range children.Repositories {
70			nodes = append(nodes, nodeFromRepository(repo, parent))
71		}
72		return nodes, nil
73	}
