75	// loadRootGroups charge les groupes racine, décorés.
76	func (m Model) loadRootGroups() tea.Cmd {
77		backend := m.shared.Forge
78	
79		return func() tea.Msg {
80			namespaces, err := backend.RootNamespaces(context.Background(), forge.BrowseOptions{Decorated: true})
81			if err != nil {
82				return LoadErrorMsg{Error: err}
83			}
84	
85			nodes := make([]*TreeNode, len(namespaces))
86			for i, ns := range namespaces {
87				nodes[i] = nodeFromNamespace(ns, nil)
88			}
89			return RootGroupsLoadedMsg{Nodes: nodes}
90		}
91	}
