93	// loadChildren charge les sous-groupes et projets d'un groupe, décorés : la vue
94	// affiche le rôle et le statut CI en colonnes.
95	//
96	// Elle liste les dépôts archivés — l'explorer montre ce qui est là.
97	// `forge.pull.include_archived` ne concerne que le clone, et c'est
98	// discoverChildren qui le lit.
99	func (m Model) loadChildren(parentNode *TreeNode) tea.Cmd {
100		backend := m.shared.Forge
101	
102		return func() tea.Msg {
103			children, err := backend.Children(context.Background(), parentNode.ID, forge.BrowseOptions{
104				IncludeArchived: true,
105				Decorated:       true,
106			})
107			if err != nil {
108				return LoadErrorMsg{Error: err, ParentNode: parentNode}
109			}
110	
111			nodes := make([]*TreeNode, 0, len(children.Namespaces)+len(children.Repositories))
112			for _, ns := range children.Namespaces {
113				nodes = append(nodes, nodeFromNamespace(ns, parentNode))
114			}
115			for _, repo := range children.Repositories {
116				nodes = append(nodes, nodeFromRepository(repo, parentNode))
117			}
118	
119			return ChildrenLoadedMsg{ParentNode: parentNode, Children: nodes}
120		}
121	}
