195	
196	// syncSummary is what the footer says once a sync batch has settled.
197	//
198	// It is posted as a footer message rather than derived like the progress line,
199	// and the difference is Rule 128's own: progress is a state, which is why it
200	// cannot carry a timer, and an outcome is an event, which is exactly what a
201	// footer message is. The old code derived both from one struct because they
202	// shared a function; once progress comes from the registry, they stop needing
203	// to be the same thing.
204	func (m Model) syncSummary(run jobs.Run) string {
205		var updated, upToDate, skipped, failed int
206		var firstSkipped, firstSkippedReason, firstFailed string
207	
208		for _, item := range run.Items {
209			switch {
210			case item.State == jobs.ItemFailed:
211				failed++
212				if firstFailed == "" {
213					firstFailed = pathBaseName(item.Target)
214				}
215			case item.State == jobs.ItemSkipped:
216				// A cancellation lands here too, and its Detail says so: the
217				// registry writes "cancelled" on an item that never ran, which
218				// reads correctly in "1 skipped (api: cancelled)".
219				skipped++
220				if firstSkipped == "" {
221					firstSkipped = pathBaseName(item.Target)
222					firstSkippedReason = item.Detail
223				}
224			case item.Detail == syncDetailUpdated:
225				updated++
226			default:
227				upToDate++
228			}
229		}
230	
231		var parts []string
232		if updated > 0 {
233			parts = append(parts, sharedcomponents.Plural(updated, "repository", "repositories")+" updated")
234		}
235		if upToDate > 0 {
236			parts = append(parts, strconv.Itoa(upToDate)+" up to date")
237		}
238		if skipped > 0 {
239			parts = append(parts, strconv.Itoa(skipped)+" skipped ("+firstSkipped+": "+firstSkippedReason+")")
240		}
241		if failed > 0 {
242			parts = append(parts, strconv.Itoa(failed)+" failed ("+firstFailed+") — check logs")
243		}
244		if m.syncUnreadable > 0 {
245			parts = append(parts, sharedcomponents.Plural(m.syncUnreadable, "directory", "directories")+" unreadable — check logs")
246		}
247		if len(parts) == 0 {
248			return "Nothing to sync"
249		}
250		return strings.Join(parts, " · ")
251	}
