	t.Helper()
	run, started := startedRun(cmd)
	if !started {
		t.Fatalf("no run was registered, want a %s over %v", kind, targets)
	}
	if run.Kind != kind {
		t.Errorf("run kind = %q, want %q", run.Kind, kind)
	}

